add_filter( 'woocommerce_get_price_html', 'perfectpixel_price_prefix_suffix', 30 );

function perfectpixel_price_prefix_suffix( $html ) {
	if ( '' === trim( wp_strip_all_tags( $html ) ) ) {
		return $html;
	}
	$prefix = trim( '{{price_prefix_text}}' );
	$suffix = trim( '{{price_suffix_text}}' );
	return ( '' !== $prefix ? '<span class="perfectpixel-price-prefix">' . esc_html( $prefix ) . '</span> ' : '' )
		. $html
		. ( '' !== $suffix ? ' <span class="perfectpixel-price-suffix">' . esc_html( $suffix ) . '</span>' : '' );
}
